const body = $input.first().json.body || $input.first().json;
const call = body?.message?.call || body;
return [{ json: {
  callerNumber: call?.customer?.number || call.callerNumber || 'Bilinmiyor',
  vapiCallId: call?.id || call.vapiCallId || null,
  transcript: call?.artifact?.transcript || call.transcript || null,
  summary: call?.analysis?.summary || call.summary || null,
  duration: call?.durationSeconds || call.duration || null,
  intent: call?.intent || 'diger',
  cost: call?.cost || null,
  recordingUrl: call?.artifact?.recordingUrl || null
}}];
